/**
 * docs/sources-review.md: everything found on Dorar, and what waits for the
 * owner. Generated by `npm run content:build`; never edit it by hand.
 */
import { formatGrading, formatSource } from './sources.ts';
import type { ContentModel, DorarSourceEntry, DorarSources } from './types.ts';

const SHORT = 70;

function short(text: string, max = SHORT): string {
  const one = text.replace(/\s+/g, ' ').trim();
  return one.length <= max ? one : `${one.slice(0, max).trimEnd()}…`;
}

/** Table cells cannot contain a pipe or a line break. */
const cell = (text: string) => text.replace(/\|/g, '\\|').replace(/\s+/g, ' ');

const REASONS: { reason: NonNullable<DorarSourceEntry['reason']>; title: string; help: string }[] =
  [
    {
      reason: 'short',
      title: 'Short phrases: is this the right hadith?',
      help: 'Four words or fewer appear in many hadith, so these are never matched automatically. The hadith shown contains the words; approve it if it is the one the book means.',
    },
    {
      reason: 'formula',
      title: 'Common formulas: which hadith?',
      help: 'Several Companions narrate these words in different hadith and settings. The strongest one is shown; approve it, or say which one fits.',
    },
    {
      reason: 'disputed',
      title: 'Scholars grade it differently',
      help: 'The hadith shown is graded acceptable by one scholar and weak by another.',
    },
    {
      reason: 'quran',
      title: 'Quran recitations',
      help: 'A hadith about reading these verses does not contain the verses, so it cannot be matched by wording. The hadith shown was found by searching for the practice.',
    },
    {
      reason: 'weakOnly',
      title: 'Only weak narrations contain the wording',
      help: 'Shipping a source would show a weak grading.',
    },
    {
      reason: 'noMatch',
      title: 'No close match on Dorar',
      help: 'Often the book describes what to do in its own words, or joins several narrations. The closest result is shown for reference only.',
    },
  ];

export function renderSourcesReview(model: ContentModel, dorar: DorarSources): string {
  const textOf = new Map(model.adhkar.map((a) => [a.id, a.texts[dorar.lang] ?? '']));
  const categoryOf = new Map(model.categories.map((c) => [c.id, c.titles[dorar.lang] ?? '']));
  const covered = new Set(dorar.entries.flatMap((e) => e.dhikrIds));
  const matched = dorar.entries.filter((e) => e.status === 'matched');
  const review = dorar.entries.filter((e) => e.status === 'review');
  const none = dorar.entries.filter((e) => e.status === 'none');
  const fadl = dorar.entries.filter((e) => e.fadl);
  const shippedFadl = matched.filter((e) => e.fadl?.approved);
  const notSearched = model.adhkar.filter((a) => !covered.has(a.id));
  const proposals = (dorar.wordingProposals ?? []).filter((p) => !p.approved);
  const applied = (dorar.wordingProposals ?? []).filter((p) => p.approved);
  const differ = matched.filter((e) => e.otherGrading);
  const count = (list: DorarSourceEntry[]) => list.reduce((n, e) => n + e.dhikrIds.length, 0);

  const ids = (e: DorarSourceEntry) => e.dhikrIds.join(', ');
  const first = (e: DorarSourceEntry) => textOf.get(e.dhikrIds[0]!) ?? '';
  const category = (e: DorarSourceEntry) =>
    categoryOf.get(model.adhkar.find((a) => a.id === e.dhikrIds[0])?.categoryId ?? 0) ?? '';

  const out: string[] = [
    '# Sources review (Dorar)',
    '',
    '> Generated by `npm run content:build` from `content-source/dorar-sources.json`. Do not edit.',
    '',
    'Every source below was copied from الموسوعة الحديثية on [dorar.net](https://dorar.net),',
    'never written from memory. A dhikr gets a source automatically only when a Dorar hadith',
    'contains its wording (90% of its words, in order) with a sahih or hasan grading, and the',
    'match is not ambiguous; otherwise the owner chooses. A fadl is shown only after the owner',
    'approves it: an exact quote from the Dorar text, or the owner\'s own words (marked "owner").',
    '',
    `- Searched on: ${dorar.retrievedOn || '—'}`,
    `- Adhkar: **${model.adhkar.length}**. With a source: **${count(matched)}**. ` +
      `No source (owner decision): **${count(none)}**. Waiting for your decision: **${count(review)}**. ` +
      `Not searched: **${notSearched.length}**.`,
    `- Fadl: **${fadl.length}** (approved: ${fadl.filter((e) => e.fadl!.approved).length}). ` +
      `Wording from Dorar: applied **${applied.length}**, waiting **${proposals.length}**.`,
    '',
    'To decide, reply with the numbers, for example: "approve F1–F5, W1–W3, R2, R7b" (R7b = option b of R7).',
    '',
  ];

  if (dorar.ownerNotes?.length) {
    out.push('## Notes', '', ...dorar.ownerNotes.map((n) => `- ${n}`), '');
  }

  out.push('## 1. Fadl waiting for approval', '');
  const waiting = fadl.filter((e) => !e.fadl!.approved);
  if (waiting.length === 0) out.push('Nothing waiting.', '');
  else {
    out.push('| # | Dhikr | Quote from Dorar | Status | Dorar |', '|---|---|---|---|---|');
    waiting.forEach((e, i) =>
      out.push(
        `| F${i + 1} | ${ids(e)} — ${cell(short(first(e), 40))} | ${cell(e.fadl!.text)} | ` +
          `${e.status === 'matched' ? 'source shipped' : 'source in R list'} | [link](${e.hadith!.url}) |`,
      ),
    );
    out.push('');
  }

  out.push('## 2. Wording from Dorar waiting for approval', '');
  if (proposals.length === 0) out.push('Nothing waiting.', '');
  else {
    out.push('| # | Dhikr | Now | From Dorar | Dorar |', '|---|---|---|---|---|');
    proposals.forEach((p, i) =>
      out.push(
        `| W${i + 1} | ${p.dhikrId} | ${cell(p.current)} | ${cell(p.proposed)} | [link](${p.hadith.url}) |`,
      ),
    );
    out.push('');
  }

  out.push('## 3. Waiting for your decision', '');
  let r = 0;
  for (const group of REASONS) {
    const items = review.filter((e) => (e.reason ?? 'noMatch') === group.reason);
    if (items.length === 0) continue;
    out.push(`### ${group.title} (${items.length})`, '', group.help, '');
    for (const e of items) {
      r++;
      out.push(`**R${r}. ${ids(e)}** — ${category(e)}`, '');
      out.push(`- Dhikr: ${short(first(e))}`);
      if (e.options && e.options.length > 1) {
        e.options.forEach((h, k) =>
          out.push(
            `- Option ${'abc'[k]}: ${short(h.text, 110)} — ${formatSource(h)} — ${formatGrading(h) ?? ''} [link](${h.url})`,
          ),
        );
      } else if (e.hadith) {
        out.push(
          `- Dorar: ${short(e.hadith.text)} — ${formatSource(e.hadith)} — ${formatGrading(e.hadith) ?? ''} [link](${e.hadith.url})`,
        );
      }
      out.push(`- Note: ${e.note}`, '');
    }
  }
  if (r === 0) out.push('Nothing waiting.', '');

  out.push(`## 4. Shipped sources where other scholars differ (${differ.length})`, '');
  if (differ.length === 0) out.push('None.', '');
  else {
    out.push(
      'The app shows the grading of the narration below. Another scholar calls the hadith weak; this is shown here only. Say if any should be removed.',
      '',
      '| Dhikr | Shown in the app | Others say |',
      '|---|---|---|',
    );
    for (const e of differ) {
      const o = e.otherGrading!;
      out.push(
        `| ${ids(e)} — ${cell(short(first(e), 40))} | ${cell(formatGrading(e.hadith!) ?? '')} ([link](${e.hadith!.url})) | ` +
          `${cell(`${o.grading} — ${o.muhaddith} (${o.book} ${o.number})`)} ([link](${o.url})) |`,
      );
    }
    out.push('');
  }

  out.push(`## 5. Fadl shown in the app (${shippedFadl.length})`, '');
  if (shippedFadl.length === 0) out.push('None yet.', '');
  else {
    out.push('| Dhikr | Fadl | Words | Dorar |', '|---|---|---|---|');
    for (const e of shippedFadl) {
      out.push(
        `| ${ids(e)} — ${cell(short(first(e), 40))} | ${cell(e.fadl!.text)} | ` +
          `${e.fadl!.by === 'owner' ? 'owner' : 'quote from Dorar'} | [link](${e.hadith!.url}) |`,
      );
    }
    out.push('');
  }

  out.push(`## 6. Wording from Dorar in the app (${applied.length})`, '');
  if (applied.length === 0) out.push('None yet.', '');
  else {
    out.push('| Dhikr | Source text | Now in the app | Dorar |', '|---|---|---|---|');
    for (const p of applied) {
      out.push(
        `| ${p.dhikrId} | ${cell(p.current)} | ${cell(p.proposed)} | [link](${p.hadith.url}) |`,
      );
    }
    out.push('');
  }

  out.push(`## 7. No source, by the owner's decision (${count(none)})`, '');
  if (none.length === 0) out.push('None.', '');
  else {
    out.push('| Dhikr | Category | Start | Note |', '|---|---|---|---|');
    for (const e of none) {
      out.push(
        `| ${ids(e)} | ${cell(category(e))} | ${cell(short(first(e), 45))} | ${cell(e.note)} |`,
      );
    }
    out.push('');
  }

  out.push(`## 8. Shipped sources (${count(matched)} adhkar)`, '');
  if (matched.length === 0) out.push('None yet.', '');
  else {
    out.push(
      '| Dhikr | Category | Start | Source | Grading | Dorar |',
      '|---|---|---|---|---|---|',
    );
    for (const e of matched) {
      out.push(
        `| ${ids(e)} | ${cell(category(e))} | ${cell(short(first(e), 45))} | ${cell(formatSource(e.hadith!))} | ` +
          `${cell(formatGrading(e.hadith!) ?? '')} | [link](${e.hadith!.url}) |`,
      );
    }
    out.push('');
  }

  out.push('## 9. Not searched', '');
  out.push(notSearched.length === 0 ? 'None.' : notSearched.map((a) => a.id).join(', '), '');
  return out.join('\n');
}
